import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Button,
  Spin,
  Table,
  notification,
  Icon
} from 'antd'
import swal from 'sweetalert2'
import PropTypes from 'prop-types'
import moment from 'moment-timezone'
import LayoutContent from '../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import ReconActions from '../../../../redux/recon/actions'
import AutoReconDetailsWrapper from './index.style'
import ReconStatus from './components/status'
import { get } from 'lodash'
import loadingAction from '../../../../../redux/loading/actions'
import ErrorAction from '../../../../../redux/error/actions'
import PermissionChecker from '../../../../../components/permissionCheckerV2'
const { resetLoadingRedux } = loadingAction
const { resetErrorRedux } = ErrorAction

const {
  getReconDetails,
  resetReduxStateRecon,
  sendReconReport,
  getReconStatus,
  downloadReport,
  // reRunRecon,
  postreconResolverUpdate
} = ReconActions

class AutoReconDetails extends React.Component {
  componentDidMount () {
    const { params } = this.props.match
    this.fetch({ query: { recon_id: params.id } })
    this.props.resetLoadingRedux(['DOWNLOAD_REPORT', 'RERUN_RECON'])
    this.props.resetErrorRedux(['DOWNLOAD_REPORT', 'RERUN_RECON'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      postStartReconLoading,
      postStartReconError,
      postStartReconMessage,
      downloadReportLoading,
      downloadReportError,
      report,
      rerunReconLoading,
      rerunReconError,
      rerunReconStatus,
      reconResolverPostFeedbackSubmit,
      reconResolverPostFeedbackSubmitMessage
    } = nextProps
    if (!postStartReconLoading && !!postStartReconMessage) {
      const isError = !!postStartReconError
      const notificationType = isError ? 'error' : 'success'
      const notificationTitle = isError ? 'Error' : 'Success'

      notification[notificationType]({
        title: notificationTitle,
        message: postStartReconMessage
      })

      this.props.resetReduxStateRecon(['postStartReconMessage'])
    }
    if (downloadReportLoading === false && downloadReportError === false) {
      this.download(report)
      this.props.resetLoadingRedux(['DOWNLOAD_REPORT'])
      this.props.resetErrorRedux(['DOWNLOAD_REPORT'])
    }
    if (rerunReconLoading === false) {
      if (rerunReconError === false) {
        this.handleStatusReload()
      }
      notification[rerunReconError ? 'error' : 'success']({
        message: rerunReconStatus
      })
      this.props.resetLoadingRedux(['RERUN_RECON'])
      this.props.resetErrorRedux(['RERUN_RECON'])
    }
    if (reconResolverPostFeedbackSubmitMessage === 'Success') {
      if (get(reconResolverPostFeedbackSubmit, 'page') === 'list') {
        this.props.history.push('/recon/feedback')
      } else {
        this.props.history.push(
          `/recon/feedback-detail/${get(
            reconResolverPostFeedbackSubmit,
            'request_id'
          )}`
        )
      }
      this.props.resetReduxStateRecon([
        'reconResolverPostFeedbackSubmitMessage',
        'reconResolverPostFeedbackSubmit'
      ])
    }
    if (
      reconResolverPostFeedbackSubmitMessage !== 'Success' &&
      reconResolverPostFeedbackSubmitMessage !== undefined
    ) {
      notification.error({
        message: reconResolverPostFeedbackSubmitMessage
      })
      this.props.resetReduxStateRecon([
        'reconResolverPostFeedbackSubmitMessage'
      ])
    }
  }

  fetch = (payload) => {
    this.props.getReconDetails(payload)
    this.props.getReconStatus(payload)
  };

  back = () => {
    const { history } = this.props
    if (history) {
      const { action } = history
      if (action === 'POP') {
        history.push('/recon/lists')
      } else {
        history.goBack()
      }
    }
  };

  handleStatusReload = () => {
    const { params } = this.props.match
    this.props.getReconStatus({ query: { recon_id: params.id } })
  };

  // handleRerun = () => {
  //   const { params } = this.props.match
  //   this.props.reRunRecon({ body: { recon_id: params.id } })
  // }

  handleSendReport = () => {
    const { profileData, match } = this.props
    const { params } = match

    swal({
      title: 'Recon report will be sent to your email',
      input: 'text',
      inputPlaceholder: 'Add comma separated emails',
      inputValue: profileData.email,
      showCancelButton: true,
      confirmButtonText: 'Send',
      showLoaderOnConfirm: true,
      preConfirm: (mail) => {
        this.props.sendReconReport({
          query: {
            id: params.id
          },
          body: {
            email_id: mail
          }
        })
      },
      allowOutsideClick: () => false
    }).then((result) => {
      if (result.dismiss !== 'cancel') {
        swal({ type: 'success', title: '', text: 'success' })
      }
    })
  };

  renderDetailRow = (key, value, key2, value2) => {
    return (
      <Row className='detail-row'>
        <Col span={6} className='recon-col-head'>
          {key}
        </Col>
        <Col span={6}>{value}</Col>
        {key2 && (
          <Col span={6} className='recon-col-head'>
            {key2}
          </Col>
        )}
        {value2 && <Col span={6}>{value2}</Col>}
      </Row>
    )
  };

  handleFeedbackPostAction = () => {
    const { reconDetails, profileData } = this.props
    const payload = {
      product_key: get(reconDetails, 'product', []).join(''),
      partner: get(reconDetails, 'partner'),
      package: get(reconDetails, 'package'),
      month: parseInt(get(reconDetails, 'from_date').split('-')[1]),
      year: parseInt(get(reconDetails, 'from_date').split('-')[0]),
      recon_id: get(reconDetails, 'id'),
      user_id: get(profileData, 'id'),
      notification: []
    }
    this.props.postreconResolverUpdate({ body: payload })
  };

  render () {
    const {
      reconDetails,
      getAutoReconDetailsLoading,
      profileData,
      rerunReconLoading,
      reconStatus,
      reconResolverPostFeedbackSubmitLoading
    } = this.props
    const fileProcess = get(reconStatus, 'status', [])
    const feedBackButtonVisible =
      fileProcess.length > 0 &&
      fileProcess[fileProcess.length - 1] === 'SUCCESS'
    const {
      name,
      partner,
      product,
      display_name: productDisplayName,
      package: packageName,
      report_file: reportFile,
      uploaded_file: uploadedFile,
      created_at: createdAt,
      from_date: fromDate,
      to_date: toDate,
      uploaded_by: uploadedBy,
      disable_resolver: disableResolver
    } = reconDetails

    const uploadedColumns = [
      {
        title: 'File Name',
        dataIndex: 'file_name',
        key: 'file_name'
      },
      {
        title: 'File Status',
        dataIndex: 'file_status',
        key: 'file_status'
      },
      {
        title: 'File Url',
        dataIndex: 'file_url',
        key: 'file_url',
        render: (data) => {
          return (
            <a href={data} disabled={!data}>
              Download
            </a>
          )
        }
      }
    ]

    const expandedRowRender = (data) => {
      const columns = [
        { title: 'No.', dataIndex: 'sheet_no', width: 30 },
        { title: 'Sheet Name', dataIndex: 'sheet_name', width: 100 },
        { title: 'Status', dataIndex: 'status', width: 100 },
        { title: 'Errors', dataIndex: 'errors' }
      ]
      return (
        <Table
          dataSource={data.file_sheets}
          columns={columns}
          pagination={false}
          className='sheet-table'
          rowKey='sheet_no'
        />
      )
    }

    return (
      <LayoutContentWrapper>
        <LayoutContent>
          <AutoReconDetailsWrapper>
            <Spin
              spinning={!!getAutoReconDetailsLoading || !!rerunReconLoading}
            >
              <Row
                className='padding-bottom'
                type='flex'
                justify='space-between'
              >
                <Button onClick={() => this.back()}>Back</Button>
                <Row type='flex' justify='space-around'>
                  {feedBackButtonVisible && (
                    <PermissionChecker requiredPermission='ops.recon_resolver'>
                      {!disableResolver && (
                        <Button
                          loading={reconResolverPostFeedbackSubmitLoading}
                          className='report-button'
                          onClick={this.handleFeedbackPostAction}
                        >
                          Resolve
                        </Button>
                      )}
                    </PermissionChecker>
                  )}
                  {/* <Button className='report-button' onClick={this.handleRerun}>
                      Re-Run
                    </Button> */}
                  {!!reportFile && (
                    <div>
                      <Button className='report-button' href={reportFile}>
                        Download Report
                      </Button>
                      <Button
                        className='report-button'
                        onClick={this.handleSendReport}
                      >
                        Send report
                      </Button>
                    </div>
                  )}
                </Row>
              </Row>
              <div className='details'>
                {this.renderDetailRow('Name', name)}
                {this.renderDetailRow('Partner', partner)}
                {this.renderDetailRow(
                  'Product',
                  productDisplayName ? productDisplayName.join(', ') : product
                )}
                {this.renderDetailRow('Package', packageName)}
                {this.renderDetailRow('From Date', fromDate, 'To Date', toDate)}
                {this.renderDetailRow(
                  'Created On',
                  moment(createdAt).tz(profileData.user_timezone).format('lll'),
                  'Created By',
                  uploadedBy
                )}
              </div>
              <Row className='recon-head' type='flex' justify='space-between'>
                STATUS
                <Icon
                  type='reload'
                  onClick={this.handleStatusReload}
                  className='reload-icon'
                />
              </Row>
              <ReconStatus />
              <Row className='recon-head'>UPLOADED FILES</Row>
              <Table
                className='uploaded-files-table'
                dataSource={uploadedFile}
                columns={uploadedColumns}
                pagination={false}
                rowKey='file_url'
                expandedRowRender={expandedRowRender}
                expandIcon={({ expanded, onExpand, record = {} }) =>
                  record.file_sheets &&
                  record.file_sheets.length > 0 &&
                  (expanded
                    ? (<Icon
                        type='down'
                        className='expand-icon'
                        onClick={(e) => onExpand(record, e)}
                       />)
                    : (<Icon
                        type='right'
                        className='expand-icon'
                        onClick={(e) => onExpand(record, e)}
                       />
                      ))}
              />
            </Spin>
          </AutoReconDetailsWrapper>
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

AutoReconDetails.propTypes = {
  reconDetails: PropTypes.object.isRequired
}

AutoReconDetails.defaultProps = {
  reconDetails: {}
}

export default connect(
  state => ({
    profileData: state.Auth.profile,

    reconDetails: state.Recon.reconDetails,
    getAutoReconDetailsLoading: state.Loading.GET_AUTO_RECON_DETAILS,
    getAutoReconDetailsError: state.Error.GET_AUTO_RECON_DETAILS,

    postStartReconLoading: state.Loading.POST_START_RECON,
    postStartReconError: state.Error.POST_START_RECON,
    postStartReconMessage: state.Recon.postStartReconMessage,

    reconStatusLoading: state.Loading.GET_RECON_DETAIL_STATUS,
    reconStatusError: state.Error.GET_RECON_DETAIL_STATUS,
    reconStatus: state.Recon.reconStatus,

    report: state.Recon.downloadReport,
    downloadReportLoading: state.Loading.DOWNLOAD_REPORT,
    downloadReportError: state.Error.DOWNLOAD_REPORT,

    rerunReconLoading: state.Loading.RERUN_RECON,
    rerunReconError: state.Error.RERUN_RECON,
    rerunReconStatus: state.Recon.rerunReconStatus,

    reconResolverPostFeedbackSubmitLoading: state.Loading.POST_RECON_FEEDBACK,
    reconResolverPostFeedbackSubmit: state.Recon.reconResolverPostFeedbackSubmit,
    reconResolverPostFeedbackSubmitMessage: state.Recon.reconResolverPostFeedbackSubmitMessage
  }),
  {
    getReconDetails,
    resetReduxStateRecon,
    sendReconReport,
    getReconStatus,
    downloadReport,
    // reRunRecon,
    resetErrorRedux,
    resetLoadingRedux,
    postreconResolverUpdate
  }
)(AutoReconDetails)
