import React, { Component } from 'react'
import { connect } from 'react-redux'
import _ from 'lodash'
import { ReconStatusStyle } from './component.style'
import { Steps, Icon, Card, Spin } from 'antd'

const { Step } = Steps

class Status extends Component {
  constructor (props) {
    super(props)
    this.state = {
      reconStatus: [],
      stepsData: [
        { status: 'wait', title: 'Created', icon: 'plus-circle', key: 'CREATED' },
        { status: 'wait', title: 'File Reading', icon: 'file-search', key: 'FILE_READING' },
        { status: 'wait', title: 'CSV Generated', icon: 'file-done', key: 'CSV_GENERATED' },
        { status: 'wait', title: 'Reconcilling', icon: 'experiment', key: 'RECONCILLING' },
        { status: 'wait', title: 'Recon Processing', icon: 'funnel-plot', key: 'RECON_PROCESSING' },
        { status: 'wait', title: 'Report Generation', icon: 'file-sync', key: 'REPORT_GENERATION' },
        { status: 'wait', title: 'Success', icon: 'check-circle', key: 'SUCCESS' }
      ]
    }
  }

  componentWillReceiveProps (nextProps) {
    const { reconStatus, stepsData } = this.state
    const { status: statusList = [], remark = '' } = nextProps.reconStatus

    if ((statusList !== reconStatus) && (nextProps.reconStatusLoading === false)) {
      statusList.forEach((status, ind) => {
        if (status === 'FAILED') {
          let statusObject = _.find(stepsData, { key: statusList[ind - 1] })
          let index = _.findIndex(stepsData, { key: statusList[ind - 1] })
          statusObject = {
            ...statusObject,
            status: 'error',
            description: remark
          }
          stepsData[index] = statusObject
          this.setState({ stepsData })
        } else {
          let statusObject = _.find(stepsData, { key: status })
          let index = _.findIndex(stepsData, { key: status })
          statusObject = {
            ...statusObject,
            status: 'finish'
          }
          if (statusList.length - 1 === ind) {
            statusObject = {
              ...statusObject,
              description: remark
            }
          } else {
            delete statusObject['description']
          }
          stepsData[index] = statusObject
          this.setState({ stepsData })
        }
      })
      for (let i = statusList.length + 1; i < stepsData.length; i++) {
        let statusObject = stepsData[i]
        statusObject = {
          ...statusObject,
          status: 'wait',
          description: ''
        }
        stepsData[i] = statusObject
      }
      this.setState({ stepsData })
      this.setState({ reconStatus: statusList })
    }
  }

  render () {
    const { reconStatusLoading } = this.props
    const { stepsData } = this.state

    return (
      <ReconStatusStyle>
        <Card>
          <Spin spinning={reconStatusLoading}>
            <Steps labelPlacement='vertical' size='small'>
              {
                stepsData.map(({ status, title, icon, description }, index) =>
                  <Step
                    status={status}
                    key={index}
                    title={title}
                    description={description && <div className='step-description'>{description}</div>}
                    icon={<Icon type={icon} />}
                  />
                )
              }
            </Steps>
          </Spin>
        </Card>
      </ReconStatusStyle>
    )
  }
}

export default connect(
  state => ({
    reconDetails: state.Recon.reconDetails,
    reconStatusLoading: state.Loading.GET_RECON_DETAIL_STATUS,
    reconStatusError: state.Error.GET_RECON_DETAIL_STATUS,
    reconStatus: state.Recon.reconStatus
  }), {

  })(Status)
